package lab.bls

import java.nio.file.Files
import lab.bls.BlsFixtures.*
import lab.cbor.Bytes

/** Vectors from outside this repository: the Leios proto-devnet's registered pool keys and proofs
  * of possession (generated by cardano-cli / cardano-base), cardano-base's serialisation negatives,
  * the consensus prototype's golden `LeiosVote`. See fixtures/leios/README.md.
  */
class MinSigVectorSuite extends munit.FunSuite:

  test("devnet pools: the secret key derives the registered verification key") {
    assertEquals(devnetPools.size, 3)
    devnetPools.foreach(p => assertEquals(right(VerificationKey.derive(p.sk)), p.vk, p.name))
  }

  test("devnet pools: registered proofs of possession verify (BLS_POP_ tag, message = key bytes)") {
    devnetPools.foreach(p => assertEquals(MinSig.verifyPossession(p.vk, p.pop), Right(()), p.name))
  }

  test(
    "devnet pools: our proof equals the registered one byte for byte (BLS signing is deterministic)"
  ) {
    devnetPools.foreach(p =>
      assertEquals(right(MinSig.provePossession(p.sk)).bytes, p.pop.bytes, p.name)
    )
  }

  test("a proof of possession does not verify for another pool's key") {
    val Vector(a, b, _) = devnetPools
    assertEquals(MinSig.verifyPossession(a.vk, b.pop), Left(BlsError.ProofOfPossessionInvalid))
  }

  test("a proof of possession is not a vote signature, and a vote signature is not a proof") {
    val p = devnetPools.head
    // the proof is a valid signature of the key bytes under the POP tag only
    assertEquals(
      MinSig.verify(p.vk, p.vk.bytes, right(Signature.fromBytes(p.pop.bytes))),
      Left(BlsError.SignatureInvalid)
    )
    val sig = right(MinSig.sign(p.sk, p.vk.bytes))
    assertEquals(
      MinSig.verifyPossession(p.vk, right(ProofOfPossession.fromBytes(sig.bytes))),
      Left(BlsError.ProofOfPossessionInvalid)
    )
  }

  test("wrong domain-separation tag fails (the AUG/NUL tag of cardano-base's other vectors)") {
    val p = devnetPools.head
    val msg = rbHash(1).bytes
    val good = right(MinSig.sign(p.sk, msg))
    assertEquals(MinSig.verify(p.vk, msg, good), Right(()))
    for dst <- Seq(
        "BLS_SIG_BLS12381G1_XMD:SHA-256_SSWU_RO_NUL_",
        "BLS_SIG_BLS12381G1_XMD:SHA-256_SSWU_RO_AUG_",
        "BLS_SIG_BLS12381G2_XMD:SHA-256_SSWU_RO_POP_",
        MinSig.possessionDst,
        ""
      )
    do
      val other = right(MinSig.signUnder(p.sk, msg, dst))
      assertEquals(
        MinSig.verifyUnder(p.vk, msg, other, MinSig.signatureDst).isLeft,
        dst != MinSig.signatureDst,
        dst
      )
  }

  // cardano-base serde_test_vectors, README order: 0 G1 uncompressed off curve, 1 G1 compressed
  // off curve, 2 G1 compressed not in group, 3 G1 uncompressed not in group, 4..7 the same in G2.
  test("cardano-base serde vectors: G1 (signature) negatives") {
    val v = serde
    assertEquals(v.size, 8)
    assertEquals(Signature.fromBytes(v(0)), Left(BlsError.WrongLength(Operand.Signature, 48, 96)))
    assertEquals(Signature.fromBytes(v(1)), Left(BlsError.MalformedPoint(Operand.Signature)))
    assertEquals(Signature.fromBytes(v(2)), Left(BlsError.NotInSubgroup(Operand.Signature)))
    assertEquals(Signature.fromBytes(v(3)), Left(BlsError.WrongLength(Operand.Signature, 48, 96)))
  }

  test("cardano-base serde vectors: G2 (verification key) negatives") {
    val v = serde
    assertEquals(
      VerificationKey.fromBytes(v(4)),
      Left(BlsError.WrongLength(Operand.VerificationKey, 96, 192))
    )
    assertEquals(
      VerificationKey.fromBytes(v(5)),
      Left(BlsError.MalformedPoint(Operand.VerificationKey))
    )
    assertEquals(
      VerificationKey.fromBytes(v(6)),
      Left(BlsError.NotInSubgroup(Operand.VerificationKey))
    )
    assertEquals(
      VerificationKey.fromBytes(v(7)),
      Left(BlsError.WrongLength(Operand.VerificationKey, 96, 192))
    )
  }

  test("infinity is rejected for keys, signatures and proofs (compressed identity encodings)") {
    val g2 = Array.fill[Byte](96)(0); g2(0) = 0xc0.toByte
    val g1 = Array.fill[Byte](48)(0); g1(0) = 0xc0.toByte
    assertEquals(
      VerificationKey.fromBytes(Bytes.wrap(g2)),
      Left(BlsError.Infinity(Operand.VerificationKey))
    )
    assertEquals(Signature.fromBytes(Bytes.wrap(g1)), Left(BlsError.Infinity(Operand.Signature)))
    assertEquals(
      ProofOfPossession.fromBytes(Bytes.wrap(g1)),
      Left(BlsError.Infinity(Operand.ProofOfPossession))
    )
  }

  test(
    "the compression flag must be set (an uncompressed-form first byte with a compressed length)"
  ) {
    val bad = devnetPools.head.vk.bytes.toArray
    bad(0) = (bad(0) & 0x7f).toByte
    assertEquals(
      VerificationKey.fromBytes(Bytes.wrap(bad)),
      Left(BlsError.NotCompressed(Operand.VerificationKey))
    )
  }

  test("zero and out-of-range secret keys are rejected") {
    assertEquals(SecretKey.fromBytes(Bytes.wrap(new Array[Byte](32))), Left(BlsError.InvalidScalar))
    assertEquals(
      SecretKey.fromBytes(Bytes.wrap(Array.fill[Byte](32)(-1))),
      Left(BlsError.InvalidScalar)
    )
    assertEquals(
      SecretKey.fromBytes(Bytes.wrap(new Array[Byte](31))),
      Left(BlsError.WrongLength(Operand.SecretKey, 32, 31))
    )
  }

  test("key generation from a seed is deterministic and yields a valid key") {
    val (sk1, vk1) = key(5)
    val (_, vk2) = key(5)
    assertEquals(vk1, vk2)
    assertNotEquals(vk1, key(6)._2)
    assertEquals(sk1.toString, "SecretKey(<secret>)")
  }

  test("golden LeiosVote of the consensus prototype decodes and re-encodes to the same bytes") {
    val golden = Bytes.wrap(Files.readAllBytes(dir.resolve("LeiosVote.golden.cbor")))
    val vote = right(Vote.decode(golden))
    assertEquals(vote.announcingRbHash.bytes, Bytes.wrap(Array.tabulate[Byte](32)(_.toByte)))
    assertEquals(vote.voter.index, 1000)
    assertEquals(vote.encode, golden)
  }
end MinSigVectorSuite
